input_grid = [
    [9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 1, 1, 1, 1, 1],
    [9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 3, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],
    [3, 9, 9, 3, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 3, 9, 9, 3, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],
    [1, 1, 1, 1, 1, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9]
]

# Analyze pattern structure
height, width = len(input_grid), len(input_grid[0])
print(f"Input grid: {height}x{width}")

# Find positions of non-9 values
non9_positions = []
for r in range(height):
    for c in range(width):
        if input_grid[r][c] != 9:
            non9_positions.append((r, c, input_grid[r][c]))

print(f"Non-9 positions: {non9_positions}")

# Sort by row, then by value
non9_by_value = {}
for pos in non9_positions:
    r, c, val = pos
    if val not in non9_by_value:
        non9_by_value[val] = []
    non9_by_value[val].append((r, c))

print(f"\nBy value:")
for val, positions in sorted(non9_by_value.items()):
    print(f"  {val}: {positions}")

# Test hypothesis: swap 1 <-> 3, keep 9s
output = [[9]*width for _ in range(height)]
for r in range(height):
    for c in range(width):
        if input_grid[r][c] == 9:
            output[r][c] = 9
        elif input_grid[r][c] == 1:
            output[r][c] = 3
        elif input_grid[r][c] == 3:
            output[r][c] = 1

print(f"\nProposed output (1↔3 swap, 9s preserved):")
for row in output:
    print(row)

